import json
from pathlib import Path
import tempfile
from urllib.parse import unquote, urlsplit

import config
import uniclubs_database


SCHEMA_VERSION = 1
SQLITE_MAX_INTEGER = 2 ** 63 - 1  # SQLite row identities use signed 64-bit integers.
AI_CITATION = 'OpenAI Codex (GPT-6), 2026-11-17, public metadata export; team review pending'
CLUB_FIELDS = ('id', 'external_id', 'name', 'source_url')
EVENT_FIELDS = (
    'id', 'external_id', 'club_id', 'title', 'start_utc', 'end_utc', 'location', 'event_type',
    'source_url', 'publication_status', 'availability_state', 'requires_membership',
    'first_seen_utc', 'last_seen_utc', 'source_missing',
)


def _text(value, field, required=True):
    """Validate a public text field without coercing numbers or missing values into text."""
    if not isinstance(value, str) or (required and not value.strip()):
        raise ValueError(f'The public snapshot has invalid {field}.')
    return value.strip()


def _positive_id(value, field):
    """Require a positive integer identity, excluding booleans and floating-point values."""
    if type(value) is not int or not 1 <= value <= SQLITE_MAX_INTEGER:
        raise ValueError(f'The public snapshot has an invalid {field}.')
    return value


def _record(value, fields, label):
    """Require every versioned field while ignoring fields outside the public whitelist."""
    if not isinstance(value, dict) or any(field not in value for field in fields):
        raise ValueError(f'The public snapshot contains an incomplete {label}.')
    return {field: value[field] for field in fields}


def _records(value, label):
    """Check a bounded list, including an explicitly empty successful catalog."""
    if not isinstance(value, list) or len(value) > config.UNICLUBS_MAX_EXPORT_RECORDS:
        raise ValueError(f'The public snapshot has an invalid {label} list.')
    return value


def _source_link(value, kind):
    """Allow only public HSG club/event links without query strings or credentials."""
    text = _text(value, 'source link')
    try:
        url = urlsplit(text)
    except ValueError as error:
        raise ValueError('The public snapshot has an invalid source link.') from error
    expected = urlsplit(config.UNICLUBS_BASE_URL)
    if (url.scheme != expected.scheme or url.netloc != expected.netloc
            or url.query or url.fragment):
        raise ValueError('Only public UniClubs source links may be exported.')
    parts = url.path.split('/')
    for part in parts:
        decoded = unquote(part)
        if decoded in ('.', '..') or '/' in decoded or '\\' in decoded:
            raise ValueError('The source link contains an invalid path segment.')
    club_path = (len(parts) >= 4 and parts[1:3] == [config.UNICLUBS_UNIVERSITY, 'clubs']
                 and parts[3] not in ('', '.', '..'))
    if not club_path:
        raise ValueError('The source link is outside the public HSG catalog.')
    if kind == 'club' and len(parts) != 4:
        raise ValueError('A public club profile link is required.')
    if kind == 'event' and (len(parts) != 6 or parts[4] != 'events'
                            or parts[5] in ('', '.', '..')):
        raise ValueError('A public event detail link is required.')
    return text


def _metadata(payload):
    """Validate the format version and successful observation carried by a snapshot."""
    fields = ('schema_version', 'ai_citation', 'source_url', 'last_success_utc')
    meta = _record(payload.get('_meta'), fields, 'metadata object')
    if type(meta['schema_version']) is not int or meta['schema_version'] != SCHEMA_VERSION:
        raise ValueError('The public snapshot schema version is not supported.')
    if meta['source_url'] != config.UNICLUBS_EVENTS_URL:
        raise ValueError('The public snapshot does not identify the expected event source.')
    meta['ai_citation'] = _text(meta['ai_citation'], 'AI citation')
    meta['last_success_utc'] = uniclubs_database.normalize_utc_time(
        meta['last_success_utc'], 'last_success_utc')
    return meta


def _club(value):
    """Return one normalized, explicitly public club record."""
    club = _record(value, CLUB_FIELDS, 'club')
    club['id'] = _positive_id(club['id'], 'club ID')
    club['external_id'] = _text(club['external_id'], 'club source ID')
    club['name'] = _text(club['name'], 'club name')
    club['source_url'] = _source_link(club['source_url'], 'club')
    return club


def _event(value, clubs, last_success):
    """Validate one event, retaining unknown values and its exact source identity."""
    event = _record(value, EVENT_FIELDS, 'event')
    event['id'] = _positive_id(event['id'], 'event ID')
    event['club_id'] = _positive_id(event['club_id'], 'event club ID')
    if event['club_id'] not in clubs:
        raise ValueError('An exported event refers to a missing club.')
    for field in ('external_id', 'title', 'publication_status', 'availability_state'):
        event[field] = _text(event[field], field)
    for field in ('location', 'event_type'):
        event[field] = _text(event[field], field, required=False)
    event['source_url'] = _source_link(event['source_url'], 'event')
    # Retained missing events may still use an older slug after the club profile changes.
    for field in ('start_utc', 'first_seen_utc', 'last_seen_utc'):
        event[field] = uniclubs_database.normalize_utc_time(event[field], field)
    if event['end_utc'] is not None:
        event['end_utc'] = uniclubs_database.normalize_utc_time(event['end_utc'], 'end_utc')
        if event['end_utc'] <= event['start_utc']:
            raise ValueError('An exported event end must follow its start.')
    if not event['first_seen_utc'] <= event['last_seen_utc'] <= last_success:
        raise ValueError('The public snapshot has inconsistent observation times.')
    if event['requires_membership'] is not None and type(event['requires_membership']) is not bool:
        raise ValueError('An exported membership requirement must be boolean or unknown.')
    if type(event['source_missing']) is not bool:
        raise ValueError('An exported source-missing marker must be boolean.')
    return event


def _unique_records(records, label):
    """Reject duplicate local or source identities before restoring any database rows."""
    local_ids, external_ids = set(), set()
    for record in records:
        if record['id'] in local_ids or record['external_id'] in external_ids:
            raise ValueError(f'The public snapshot contains duplicate {label} identities.')
        local_ids.add(record['id'])
        external_ids.add(record['external_id'])


def validate_export(payload):
    """Validate and normalize only the versioned public fields of a decoded JSON document.

    :param payload: decoded dictionary containing _meta, clubs and events
    :return: deterministic dictionary safe for export or restoration
    """
    if not isinstance(payload, dict):
        raise ValueError('The public snapshot must be an object.')
    meta = _metadata(payload)
    clubs = [_club(value) for value in _records(payload.get('clubs'), 'club')]
    _unique_records(clubs, 'club')
    club_lookup = {club['id']: club for club in clubs}
    events = [_event(value, club_lookup, meta['last_success_utc'])
              for value in _records(payload.get('events'), 'event')]
    _unique_records(events, 'event')
    clubs.sort(key=lambda club: club['id'])
    events.sort(key=lambda event: event['id'])
    return {'_meta': meta, 'clubs': clubs, 'events': events}


def _database_flag(value, nullable=False):
    """Convert a constrained SQLite integer flag to an explicit JSON boolean."""
    if value is None and nullable:
        return None
    if type(value) is not int or value not in (0, 1):
        raise ValueError('The catalog contains an invalid public boolean flag.')
    return bool(value)


def build_export(connection):
    """Read one consistent catalog snapshot using an explicit whitelist of public columns.

    :param connection: initialized, idle independent UniClubs catalog connection
    :return: validated public document; requires a previous successful import or restoration
    """
    if connection.in_transaction:
        raise ValueError('Finish the current transaction before exporting the catalog.')
    # Course: A07 – a read transaction keeps the three queries on one consistent snapshot.
    with connection:
        connection.execute('BEGIN')
        success = connection.execute('''SELECT imported_at_utc FROM import_log
            WHERE status='success' ORDER BY imported_at_utc DESC, id DESC LIMIT 1''').fetchone()
        if success is None:
            raise ValueError('A successful catalog observation is required before export.')
        clubs = connection.execute('''SELECT id, external_id, name, source_url
            FROM clubs ORDER BY id''').fetchall()
        rows = connection.execute('''SELECT id, external_id, club_id, title, start_utc,
            end_utc, location, event_type, source_url, publication_status, availability_state,
            requires_membership, first_seen_utc, last_seen_utc, source_missing
            FROM events ORDER BY id''').fetchall()
    events = []
    for row in rows:
        event = dict(row)
        event['requires_membership'] = _database_flag(event['requires_membership'], nullable=True)
        event['source_missing'] = _database_flag(event['source_missing'])
        events.append(event)
    payload = {'_meta': {'schema_version': SCHEMA_VERSION, 'ai_citation': AI_CITATION,
                         'source_url': config.UNICLUBS_EVENTS_URL,
                         'last_success_utc': success['imported_at_utc']},
               'clubs': [dict(club) for club in clubs], 'events': events}
    return validate_export(payload)


def _export_target(connection, path):
    """Reject database paths before replacing an export file, including attached databases."""
    target = Path(path).resolve()
    protected = {config.DB_FILE.resolve(), config.UNICLUBS_DB_FILE.resolve()}
    for row in connection.execute('PRAGMA database_list').fetchall():
        if row[2]:
            protected.add(Path(row[2]).resolve())
    if target in protected:
        raise ValueError('The public export must not replace a SQLite database file.')
    return target


def write_export(connection, path=config.UNICLUBS_EXPORT_FILE):
    """Replace a UTF-8 JSON export atomically after validating the complete catalog.

    :param connection: idle independent catalog connection
    :param path: public JSON target; database paths are rejected
    :return: exported public document
    """
    target = _export_target(connection, path)
    document = build_export(connection)
    content = json.dumps(document, ensure_ascii=False, indent=2, sort_keys=True) + '\n'
    if len(content.encode('utf-8')) > config.UNICLUBS_MAX_EXPORT_BYTES:
        raise ValueError('The public export exceeds the file-size limit.')
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', dir=target.parent,
                                         prefix='.' + target.name + '.', suffix='.tmp',
                                         delete=False) as stream:
            temporary = Path(stream.name)
            stream.write(content)
        temporary.replace(target)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)
    return document


def _prepare_sqlite(path, document):
    """Build a fresh public schema instead of copying unknown private tables or columns."""
    catalog = uniclubs_database.get_connection(path)
    try:
        uniclubs_database.init_db(catalog)
        restore_export(catalog, document)
        if catalog.execute('PRAGMA integrity_check').fetchone()[0] != 'ok':
            raise ValueError('The export failed its SQLite integrity check.')
        if catalog.execute('PRAGMA foreign_key_check').fetchone() is not None:
            raise ValueError('The export contains broken club references.')
    finally:
        catalog.close()


def write_sqlite(connection, path=None):
    """Replace a shareable public database atomically, keeping the old file on failure.

    :param connection: idle independent catalog connection
    :param path: separate public file; runtime paths are rejected
    :return: validated document used to build the export
    """
    target = _export_target(connection, config.UNICLUBS_SQLITE if path is None else path)
    document = build_export(connection)
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(dir=target.parent, prefix='.' + target.name,
                                         suffix='.tmp', delete=False) as stream:
            temporary = Path(stream.name)
        _prepare_sqlite(temporary, document)
        if temporary.stat().st_size > config.UNICLUBS_MAX_EXPORT_BYTES:
            raise ValueError('The export exceeds the file-size limit.')
        temporary.replace(target)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)
    return document


def restore_export(connection, payload):
    """Restore a validated snapshot only into an empty independent catalog, preserving IDs.

    :param connection: initialized catalog with no clubs, events, logs or pending transaction
    :param payload: decoded public snapshot; corrupted snapshots raise ValueError
    :return: None; restoration and its one success log commit together
    """
    if connection.in_transaction:
        raise ValueError('Finish the current transaction before restoring the catalog.')
    document = validate_export(payload)
    with connection:
        connection.execute('BEGIN IMMEDIATE')
        exists = connection.execute('''SELECT EXISTS (SELECT 1 FROM clubs)
            OR EXISTS (SELECT 1 FROM events) OR EXISTS (SELECT 1 FROM import_log)''').fetchone()[0]
        if exists:
            raise ValueError('Restore the public snapshot only into an empty catalog.')
        _restore_rows(connection, document)


def _restore_rows(connection, document):
    """Write the validated public fields within the caller's restoration transaction."""
    for club in document['clubs']:
        connection.execute('''INSERT INTO clubs (id, external_id, name, source_url)
            VALUES (?, ?, ?, ?)''', tuple(club[field] for field in CLUB_FIELDS))
    for event in document['events']:
        connection.execute('''INSERT INTO events (id, external_id, club_id, title, start_utc,
            end_utc, location, event_type, source_url, publication_status, availability_state,
            requires_membership, first_seen_utc, last_seen_utc, source_missing)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)''',
                           tuple(event[field] for field in EVENT_FIELDS))
    connection.execute(uniclubs_database.INSERT_LOG_SQL,
                       (document['_meta']['last_success_utc'], 'success', len(document['events']),
                        'Restored public catalog snapshot.'))
